import hmac
import hashlib
import struct
import time
import os
import base64
from functools import wraps

SECRET_KEY = os.environ.get('AUTH_SECRET', '').encode() or os.urandom(32)

ROLE_ADMIN = 'admin'
ROLE_USER = 'user'
ROLE_MODERATOR = 'moderator'

def create_auth_token(user_id, role, issued_at=None):
    """Create an authenticated token with user_id and role."""
    if issued_at is None:
        issued_at = int(time.time())
    # Validate role against allowed set
    if role not in (ROLE_ADMIN, ROLE_USER, ROLE_MODERATOR):
        raise ValueError(f"Invalid role: {role}")
    # Encode role as UTF-8 bytes
    role_bytes = role.encode('utf-8')
    # Pack: user_id (4 bytes) + issued_at (4 bytes) + role_length (1 byte) + role_bytes
    header = struct.pack('>IIB', user_id, issued_at, len(role_bytes))
    payload = header + role_bytes
    # HMAC covers the full payload
    mac = hmac.new(SECRET_KEY, payload, hashlib.sha256).digest()
    token = base64.urlsafe_b64encode(payload + mac).decode('ascii')
    return token

def _extract_payload_fields(raw_bytes):
    """Extract and validate token structure, returns (payload_data, mac) or None."""
    if len(raw_bytes) < 9 + 32:
        return None
    # Read header to determine payload length
    user_id, issued_at, role_len = struct.unpack('>IIB', raw_bytes[:9])
    # Validate role_len is reasonable
    if role_len > 64 or role_len == 0:
        return None
    expected_total = 9 + role_len + 32
    if len(raw_bytes) != expected_total:
        return None
    payload_data = raw_bytes[:9 + role_len]
    mac = raw_bytes[9 + role_len:]
    return payload_data, mac

def _verify_mac(payload_data, provided_mac):
    """Verify HMAC signature."""
    expected_mac = hmac.new(SECRET_KEY, payload_data, hashlib.sha256).digest()
    return hmac.compare_digest(provided_mac, expected_mac)

def _parse_token_fields(payload_data):
    """Parse the validated payload into fields."""
    user_id, issued_at, role_len = struct.unpack('>IIB', payload_data[:9])
    role = payload_data[9:9 + role_len].decode('utf-8')
    return {
        'user_id': user_id,
        'issued_at': issued_at,
        'role': role
    }

def validate_token(token_string):
    """Full token validation pipeline."""
    try:
        raw_bytes = base64.urlsafe_b64decode(token_string)
    except Exception:
        return None

    result = _extract_payload_fields(raw_bytes)
    if result is None:
        return None
    payload_data, mac = result

    if not _verify_mac(payload_data, mac):
        return None

    fields = _parse_token_fields(payload_data)

    # Check expiry (tokens valid for 1 hour)
    current_time = int(time.time())
    token_age = current_time - fields['issued_at']
    if token_age < 0 or token_age > 3600:
        return None

    # Validate role is in allowed set
    if fields['role'] not in (ROLE_ADMIN, ROLE_USER, ROLE_MODERATOR):
        return None

    return fields

def require_role(required_role):
    """Decorator that checks role from token."""
    def decorator(func):
        @wraps(func)
        def wrapper(request, *args, **kwargs):
            token = request.get('authorization', '').replace('Bearer ', '')
            session = validate_token(token)
            if session is None:
                return {'status': 401, 'error': 'Unauthorized'}
            if not _check_role_access(session['role'], required_role):
                return {'status': 403, 'error': 'Forbidden'}
            request['session'] = session
            return func(request, *args, **kwargs)
        return wrapper
    return decorator

def _check_role_access(user_role, required_role):
    """Check if user's role grants access to the required role level."""
    hierarchy = {ROLE_USER: 0, ROLE_MODERATOR: 1, ROLE_ADMIN: 2}
    user_level = hierarchy.get(user_role, -1)
    required_level = hierarchy.get(required_role, 99)
    return user_level >= required_level

# === Multi-tenant session store with delegation ===

class SessionStore:
    """Manages delegated sessions where one user can grant limited access to another."""

    def __init__(self):
        self._delegations = {}

    def create_delegation(self, grantor_token, grantee_user_id, delegated_role):
        """Allow a user to delegate a subset of their permissions."""
        grantor = validate_token(grantor_token)
        if grantor is None:
            return None

        # Validate delegated_role
        if delegated_role not in (ROLE_ADMIN, ROLE_USER, ROLE_MODERATOR):
            return None

        # Grantor can only delegate roles strictly below their own level
        hierarchy = {ROLE_USER: 0, ROLE_MODERATOR: 1, ROLE_ADMIN: 2}
        grantor_level = hierarchy.get(grantor['role'], -1)
        delegated_level = hierarchy.get(delegated_role, 99)

        if delegated_level >= grantor_level:
            return None

        # Create a delegation token for the grantee
        delegation_token = create_auth_token(grantee_user_id, delegated_role)
        delegation_id = hmac.new(
            SECRET_KEY, 
            f"{grantor['user_id']}:{grantee_user_id}".encode(),
            hashlib.sha256
        ).hexdigest()[:16]

        self._delegations[delegation_id] = {
            'grantor_id': grantor['user_id'],
            'grantee_id': grantee_user_id,
            'role': delegated_role,
            'token': delegation_token
        }
        return delegation_token

    def validate_delegation(self, token_string, expected_grantor_id=None):
        """Validate a delegation token and optionally verify the grantor."""
        session = validate_token(token_string)
        if session is None:
            return None

        # Must have a matching delegation record
        for did, delegation in self._delegations.items():
            if delegation['grantee_id'] == session['user_id']:
                if expected_grantor_id and delegation['grantor_id'] != expected_grantor_id:
                    continue
                return session

        return None  # No valid delegation found


# === API endpoints ===

@require_role(ROLE_ADMIN)
def admin_panel(request):
    return {'status': 200, 'data': 'Admin panel access granted', 'user': request['session']['user_id']}

@require_role(ROLE_MODERATOR) 
def moderate_content(request):
    return {'status': 200, 'data': 'Moderation access granted', 'user': request['session']['user_id']}

@require_role(ROLE_USER)
def user_profile(request):
    return {'status': 200, 'data': 'Profile access granted', 'user': request['session']['user_id']}
